window.VD=window.VD||{};window.VD["vw/caddy-2k"]={"caddy-2k-facelift-activate-coming-leaving-home":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose: </strong>Activates Coming Home and Leaving Home. And add it to the ODB (MFA)  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>12</strong>:<br/>Disable bit <strong>2</strong><em>“Coming-Home Mode (0 = Automatic / 1 = Manual)</em>”<br/>Set bit <strong>2</strong> for display in ODB (MFA)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cominghomeg6-f70c52d7.webp\"/></figure>\n<p>Byte <strong>17</strong>:</p>\n<p>Bit <strong>5</strong>: Check “Coming-Home (CH) active”<br/>Bit <strong>6</strong>: Check “Leaving-Home (CH) active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cominghomeg62-efef7c12.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cominghomeg63-3c107aa3.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cominghomeg64-189ea28a.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cominghomeg65-b5621af6.webp\"/></figure>","caddy-2k-facelift-activate-daytime-running-lights-drl-only-with-headlight-switch-in-auto-position":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate daytime running lights (DRL) only when the light <strong>switch</strong> is in Auto position.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>26</strong>: <br/>Bit <strong>3</strong>: Check “Daytime Running Light (DRL) only active with Assistance Driving Light (ADL) active”.  </p>","caddy-2k-facelift-activate-driving-school-mode-rcd-210-rcd-310":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to add a Driving School mode view to the RCD 210, RCD 310 that displays turn signals, speed … (Also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“56 – Radio</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“1</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/golf6_golf_vi_fahrschulfunktion-5b883ac1.webp\"/></figure>","caddy-2k-facelift-activate-hidden-menu-rns-315":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: to activate the hidden menu in RNS 315.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Developer mode (temporary)</strong> </em>then set the value to <strong><em>Enabled</em></strong></p>\n<p><em>Restart RNS 315.</em></p>\n<p><em>To launch the Hidden Menu, press SETUP (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-035-279_Module37_Adaptation_Developer_mode_tem-59109da4.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns-315-bt-8b82eb41.webp\"/></figure>","caddy-2k-facelift-activate-hidden-menu-rns-510":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: Activates the hidden menu in RNS 510.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>56 – Radio</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 50</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>Restart the RNS 510.</em></p>\n<p><em>To launch the Hidden Menu, press SETUP (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/1T0-035-680-C_Module37_Adaptation_Channel50-1a7d6a90.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","caddy-2k-facelift-activate-reversing-camera-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the rearview camera after it has been installed on the RCD 510/330/360/440 and RNS 315/510 (retrofit).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>37 – Navigation</strong> ” (RNS) or “<strong>56 – Radio</strong>” (RCD)<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>3</strong><br/>. Then set bit <strong>6</strong> to “Rear View Camera (RVC) installed/active.”</p>\n<p><strong><strong><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong></strong></strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>0</strong><br/>. Then set bit <strong>5</strong> to “Rear View Camera installed.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/CA86A611-2F74-4201-B791-7A74BC107A01-1024x482-c9f00e16.webp\"/></figure>\n<p><br/><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The two pins from the backup camera are used in the 12-pin Quadlock connector (blue).<br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","caddy-2k-facelift-activating-bluetooth-on-the-rns-315":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: to activate Bluetooth on the RNS 315.  </p>\n<p><strong>ATTENTION: Not all RNS-315 are equipped with a Bluetooth module.</strong> </p>\n<figure><table><thead><tr><td>Module compatibility list</td></tr></thead><tbody><tr><td>3C0 035 279</td><td>Yes</td></tr><tr><td>3C0 035 279 A</td><td>Yes</td></tr><tr><td>3C0 035 279 B</td><td>Yes</td></tr><tr><td>3C0 035 279 C</td><td>Yes (conditional)</td></tr><tr><td>3C0 035 279 D</td><td>No</td></tr><tr><td>3C0 035 279 E</td><td>No</td></tr><tr><td>3C0 035 279 F</td><td>No</td></tr><tr><td>3C0 035 279 G</td><td>Yes</td></tr><tr><td>3C0 035 279 H</td><td>Yes</td></tr><tr><td>3C0 035 279 J</td><td>No</td></tr><tr><td>3C0 035 279 K</td><td>No</td></tr></tbody></table></figure>\n<p>You can also remove the RNS 315 from its slot to check. Behind it, you’ll find a label with the RNS-315’s MAC address.<br/>If the MAC address contains only zeros (MAC: 00:00:00:00:00:00), your RNS-315 is not equipped with the Bluetooth module. </p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns_315_j_mac_non-6328b9e5.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns315_mac_oui-eed1a386.webp\"/></figure>\n</figure>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>3</strong><br/>Bit <strong>5</strong>: Uncheck the “Telephone Transceiver inactive” box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS315_3C0-035-279_Module37_Byte3-74e93c9c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns-315-bt-8b82eb41.webp\"/></figure>","caddy-2k-facelift-activating-rns-510-voice-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: to activate voice control on the RNS 510 (SDS).  </p>\n<p><strong>ATTENTION:</strong> RNS 510 firmware must be version v2660.</p>\n<p>Activating voice control brings up the “Voice control” menu in the RNS 510’s SETUP menu.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>3</strong>, check the box for<strong>“Bit 1: Microphone Diagnostics active</strong>”.</p>\n<p>Byte <strong>7</strong>, uncheck the box for<strong>“Bit 1: Voice Control inactive</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS510_Menu_Commande_Vocale-bf5955d7.webp\"/></figure>\n<p>To install the microphone, connect the microphone lead to the rear of the RNS 510. Connect to pins (Mic-)C1 and (Mic+)C7. </p>","caddy-2k-facelift-add-daytime-running-lights-drl-to-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to enable or disable daytime running lights (DRL) in the ODB (MFA). (2011+)</p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>15</strong>: Bit <strong>7</strong>: Check “Daytime Running Light (DRL) Active Adaptation (MFA+)”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlmfag6-54cdc95d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlmfag62-c1d9cfb9.webp\"/></figure>","caddy-2k-facelift-automatic-closing-of-windows-and-roof-in-the-event-of-rain":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: Automatically closes the windows and sunroof when it rains. </p>\n<p>The vehicle must be locked using the remote control for this to work. </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf561-c90da3e5.webp\"/></figure>\n<p><strong>5</strong> – Select module “2” and click ” <strong>Long Coding Helper</strong> “:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf56-9439cbb9.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select byte <strong>0</strong> and check bit <strong>2</strong> “<strong>Rain Closing active</strong>” to activate window and roof closing when it rains:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-5-d61c5dd9.webp\"/></figure>\n<p>7 – After completing this step, click on the “Exit” menu</p>\n<p> Then click “OK”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-7-353fb01b.webp\"/></figure>\n<p><strong>Line 2</strong>:</p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 –</strong> Select <em>Byte<strong> 4</strong>: </em><br/><em>Bit <strong>5</strong>: Check “Comfort Operation Windows/Sunroof via Rain Sensor (0 = nonrecurring / 1 = permanent)” </em><br/><em>Bit <strong>6: </strong> Check “Comfort Operation Windows/Sunroof via Rain Sensor (Rain Closing) active” </em> </p>","caddy-2k-facelift-automatic-door-locking":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Cent. Elect</strong>.”</p>\n<p><strong>4</strong> – Click “<strong>Adaptation 10</strong>.”</p>\n<p><strong>5 </strong>– Channel 04 (Auto-Lock drop-down list) <em>Set value to <strong>1</strong></em></p>\n<p><strong>Line 2 If the adaptation channel is not enabled.</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>“.</p>\n<p><strong>4 – </strong> Click “<strong>Encoding – 07</strong>,” then “<strong>Long Coding Helper”</strong></p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>2 : </strong> Check “Auto-Lock active”. </em> </p>","caddy-2k-facelift-automatic-door-unlocking":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><em>09 – Cent. Elect.</em></strong></strong>”.</p>\n<p><strong>4 – </strong> Click “<strong>Encoding – 07</strong>,” then “<strong>Long Coding Helper”</strong></p>\n<p><em>Byte <strong>0 : </strong></em><br/><em>Bit <strong>1</strong>: Check “Auto-Unlock active”. </em> </p>","caddy-2k-facelift-automatic-headlamp-activation-in-the-event-of-rain":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte 0 Bit 1: Check “Rain Light Function Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","caddy-2k-facelift-automatic-headlamps-from-140-km-h":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte 0 Bit 0: Check “Highway Light Function active above (140kph/90mph)”. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","caddy-2k-facelift-changing-the-image-of-the-rcd-rns-ops":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to change the vehicle image of the OPS (parking aid) on the RCD 510/330/360/440 and RNS 315/510.  </p>\n<p><strong>Procedure: </strong><br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>37 – Navigation</strong> ” (RNS) or “<strong>56 – Radio</strong>” (RCD)</p>\n<p><strong>4</strong> – Click “<strong>Encoding 07</strong>,” then ” <strong>Long Coding Helper</strong> “</p>\n<p><strong>5</strong> – Choose Byte<strong> 6</strong> or <strong>9</strong></p>\n<p><i>Select the vehicle</i><em>from the drop-down menu </em><i>:</i><br/><br/>00 = via CAN<br/>01 = Polo 6R<br/>02 = New Beetle<br/>03 = New Beetle Cabrio<br/>04 = Scirocco<br/>05 = Golf 5<br/>06 = Jetta<br/>07 = Golf 6 Variant<br/>08 = Golf 6 Cabrio<br/>09 = Touran<br/>0A = Golf Plus<br/>0C = Tiguan<br/>0D = Sharan<br/>0E = EOS<br/>0F = Passat 3C<br/>10 = Passat Limousine<br/>11 = Passat Variant<br/>13 = Caddy<br/>14 = T5<br/>2C = Skoda Octavia<br/>2D = Skoda Octavia Kombi<br/>2E = Skoda Superb Kombi</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0863-9500c82e.webp\"/></figure>\n<p>Exit the module and save your changes. The RCD or RNS must now be restarted for the changes to take effect. Press both arrows and the star for 6s.  </p>","caddy-2k-facelift-changing-the-rcd-rns-510-theme":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to change the display theme of the RCD 510 and RNS 510.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>” for RNS510 and “<strong>56 – Radio</strong>” for RCD510.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong></p>\n<p><em>Bit <strong>4-5</strong>: Select from 3 themes</em><br/><em>“00 Display Variant: Highline</em><br/><em>“10 Display Variant: Sportsline</em><br/><em>“20 Display Variant: Premium</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/69C76009-6EC7-465A-A676-8E39BA840A6B-6689b9e0.webp\"/><figcaption>Highline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3A58F148-9FBB-4DD8-BF05-E03A5351E3A8-e9b6cb9b.webp\"/><figcaption>Sportsline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4894A3B7-2ED2-4A75-9D46-CA3BFCF5A76C-8fb8de15.webp\"/><figcaption>Premium</figcaption></figure>\n<p>Exit the module and save your changes. The RCD / RNS 510 must now be restarted for the changes to take effect. Press both arrows and the star for 6s.  </p>","caddy-2k-facelift-checking-the-needles":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. When you start your Caddy, the speedometer hands move back and forth from minimum to maximum. (Needle Sweep)  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>10-Adaptation</strong>” then in the window that appears, click on the drop-down menu to choose a channel and select the “<strong>Staging</strong>” channel, if unavailable select the “<strong>indicator_celebration</strong>” channel:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg6-9456b738.webp\"/></figure>\n<p><strong>5</strong> – In the “<strong>New value</strong>” box, click on the drop-down menu and select “<strong>active</strong>”. Once this new value has been entered, click on “<strong>Save</strong>”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg62-c8918051.webp\"/></figure>","caddy-2k-facelift-comfort-turn-signal":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Comfort Turn Signal</strong>.”<br/><br/><strong>7</strong> – Choose between “<strong>1</strong>” and “<strong>5</strong>,” then confirm.</p>","caddy-2k-facelift-corner-lights-activation":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: Activating the <strong>turn signals</strong> causes the fog light on the side toward which you’re turning the steering wheel to turn on when traveling at speeds below 50 km/h. This feature is also called “cornering lights.” Once this feature is activated, the fog light on the side of the turn you’re making will turn on! It’s super handy on narrow roads or in roundabouts.     </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Power Control Unit</strong>.”</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4-Activation-des-feux-en-virage-sur-Golf-5-et-6-f4e51c90.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select  </p>\n<p><em>Byte <strong>12</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Cornering Light Activation Time Limited”</em></p>\n<p><em>Byte <strong>14: </strong></em><br/><em>Bit <strong>7: </strong> Check “Cornering Lights via Front Fog Lights active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5-Activation-de-la-fonction-Cornering-Lights-via-F-255e876b.webp\"/></figure>\n<p><strong>7</strong> – After completing this step, click on the “Exit” menu<br/>, then click “OK.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6-Activation-de-la-fonction-Cornering-Lights-via-F-2a08cc40.webp\"/></figure>","caddy-2k-facelift-cruise-control-activation-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose </strong>: to activate GRA cruise control (retrofit). </p>\n<p><strong>Modification only possible after retrofitting cruise control switch and <a href=\"https://wiki.ross-tech.com/wiki/index.php/Steering_Wheel_Control_Module_Versions\" rel=\"noopener\" target=\"_blank\">check that your multifunction steering wheel is compatible (midline or highline)</a>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.<br/><br/><strong>4 </strong>– Click on ” <strong>Coding II (11) or Login 11</strong> “. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur1-1c279499.webp\"/></figure>\n<p><strong>5</strong> – Then enter code <strong>11463</strong>, then <strong>OK</strong> (Do It!)</p>\n<p>The code 11463 is used to <strong>activate</strong> the controller, to <strong>deactivate</strong> it if necessary the code is 16167.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>16 – Multifunction handwheel</strong> “.<br/><br/>4<strong>– </strong>Click on ” <strong>Coding – 07</strong> “. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur3-945b80f3.webp\"/></figure>\n<p><strong>5</strong> – Options: We note in the penultimate section (0xxxx<strong>?</strong>x):<br/><br/>0 = No regulator installed (CCS not installed)<br/>1 = Regulator installed with 6 positions on a separate switch (CCS with 6 positions …. etc)<br/>3 = Regulator installed with 4 positions on the blinker switch (CCS with 4 positions via Blinker Stalk)</p>\n<p>So replace the “<strong>?</strong>” with the 3 for commodo regulator.</p>\n<p><strong>Line 3:</strong><br/><br/>3 – Click on ” <strong>Select”, then click on ” Select</strong> “. <strong><strong>01 – Engine</strong></strong> ” .<br/><br/>4 – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5 – </strong>Select byte<strong>“5</strong>“<br/>Check bit<strong>“5</strong>” Cruise Control System (CCS) installed</p>\n<p>Or byte <strong>6</strong> bit <strong>0</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur5-1024x491-af7739d1.webp\"/></figure>","caddy-2k-facelift-daytime-running-lights-drl-off-with-handbrake-on":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose: </strong>to deactivate the daytime running lights (DRL) when the handbrake is engaged. (After the end of 2009)   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>0</strong>: If this is a hidden bit, replace the last <strong>0</strong> on the right side of the binary number with <strong>a 1</strong>. (<strong>10001000</strong> =&gt; <strong>10001001</strong>)</em></p>","caddy-2k-facelift-deactivate-automatic-rear-window-wiper":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p> <strong> Purpose:</strong> to deactivate the automatic activation of the rear wiper or to suppress it.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on <strong>“Long Coding Helper”</strong>:</p>\n<p><em>Byte <strong>21</strong>: </em><br/><em>Bit <strong>2</strong>: Uncheck “Automatic Rear Window Wiping with Front Wiper at ‘Interval’ active”.</em><br/><em>Bit<strong> 3</strong>: Uncheck “Automatic Rear Window Wiping with Front Wiper at ‘Permanent’ active”.</em><br/><em>Bit <strong>6: </strong> Uncheck “Automatic Rear Window Wiping with Reverse Gear active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5K0-937-086-M_Module09_Byte21-499f6b9b.webp\"/></figure>\n<p>To completely deactivate the rear wiper after disassembly for wiper removal style with pad:</p>\n<p>Byte<strong> 21</strong>: Deactivate Bit <strong>0</strong><em> </em><em>“Rear Wiper installed</em>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/essuieglacearriereoffg6-252a2868.webp\"/></figure>","caddy-2k-facelift-deactivate-brake-pad-warning-light":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>17 – Instruments</strong>“.</p>\n<p><strong>4</strong> – Cliquer sur « <strong>Codage – 07</strong> » puis cliquer sur « <strong>Assistant Codage Long</strong>« .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>: “<br/>” Then uncheck bit <strong>0: </strong> <strong>“Brakepad warning active/installed”</strong> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","caddy-2k-facelift-deactivating-the-windscreen-washer-indicator":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>2: </strong>“<strong>Washer Fluid warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","caddy-2k-facelift-delete-odb-error-led-license-plate-illumination":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Eliminates the error on the ODB when replacing original license plate light bulbs with non-error LEDs.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .<br/><br/><strong>4 </strong>– Click on “<strong> Coding – 07 </strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em><strong>Byte 11 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “</em>Lamp diagnotics for Lisense Plate Light active<em>”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte11-e6e5cf22.webp\"/></figure>\n<p>Or</p>\n<p>Byte <strong>23</strong>:<br/>Bit <strong>6</strong>: Uncheck: “Lamp Monitoring (Cold) License Plate Lamps Active”.</p>","caddy-2k-facelift-door-lock-unlock-confirmation-beep":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose: Enables </strong>confirmation of vehicle locking/unlocking via beeps (in conjunction with the alarm) and adds the beep selection menu to the ODB (MFA).  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><strong>6 – </strong> Select Byte <strong>5</strong>:</p>\n<p>Bit <strong>1</strong>: Check “Locking Confirmation via Horn Active”<br/>Bit <strong>4: </strong> Check “Unlocking Confirmation via Horn Active”</p>\n<p>To add the beep selection menu to the ODB (MFA):</p>\n<p>Bit <strong>2</strong>: Disable “<em> </em>” “<em>Horn Confirmation Adaptation Blocked (Adaptation Channel 010/011 &amp; MFA+/FIS)</em>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng6-2ffc7685.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng62-14ab4a90.webp\"/></figure>","caddy-2k-facelift-electronic-differential-lock-xds":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the electronic differential lock (XDS).  </p>\n<p>The electronic differential lock (XDS) is an extension of the well-known EDS function. However, XDS does not react to acceleration slip, but rather relieves pressure on the inside front wheel when cornering. XDS applies pressure to the inside wheel during cornering from the hydraulic ESP to prevent slippage.   </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>03 – ABS</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><em>Byte 17 : </em><br/><em>Bit 3: Tick “(Extended) Electronic Differential Lock (XDS – PR-UG3/UG4) active/installed”</em></p>\n<p><strong>Line 2 XDS setting.</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>03 – ABS</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10 </strong>”.  </p>\n<p>Channel 36 (Electronic Differential Lock (XDS) in drop-down list)</p>\n<p><em>Choose a value</em><br/> 0<em>“medium” </em><br/>1 “low” <br/>2 “high  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/xdsg6-567d8998.webp\"/></figure>","caddy-2k-facelift-flash-mode-lights-during-emergency-braking":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong><br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port. <br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Emergency Brake Flashing via Brake Light active” (to activate brake lights)</em><br/><em>Bit <strong>2</strong>: Check “Emergency Brake Flashing via Turn Signal active” (to activate turn signals)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/emergencybreakg6-7e26fa37.webp\"/></figure>","caddy-2k-facelift-hill-hold-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose: Enables </strong>Hill Hold Control (Hill Start Assist).  </p>\n<p>Hill Hold Control maintains brake pressure for a few seconds after the brake pedal is held down for an extended period.</p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Coding – 07</strong>,” then “<strong>Long Coding Helper</strong>“</p>\n<p><em>Byte <strong>16: </strong></em><br/><em>Bit <strong>3</strong>: Check “Hill Hold Control (HHC/PR-UG1/UG4) active/installed”</em></p>\n<p><strong>Line 2: Hill Hold Control Settings.</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p>Select <strong>Channel 58</strong> (Hill Hold Control (HHC) from the drop-down list)</p>\n<p>Select a value:<br/>0 “normal”<br/>1 “earlier” (restarts with lower acceleration)<br/>2 “later” (restarts with higher acceleration)</p>","caddy-2k-facelift-locking-the-cd-dvd-eject-button-on-the-rns-510":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: locks/unlocks the RNS 510’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 43</strong> (Ejection Lock)</em> then set the value to <strong>1</strong> <em>(CD/DVD Ejection Lock active)</em></p>\n<p><em>Restart the RNS 510.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","caddy-2k-facelift-lowering-the-passenger-mirror-when-reversing":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> automatically lowers the passenger mirror when reversing.  </p>\n<p>The mirror adjustment knob must be in position<strong>“R”</strong> for the passenger mirror to lower automatically.  </p>\n<p><strong>Procedure:</strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>09 – Centrale Elec</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/retrogolf61-d4a12d4d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/retrogolf62-a22a3a65.webp\"/></figure>\n<p><strong>5</strong> – In the window that appears, select byte<strong> 4</strong> and check bit <strong>3 “</strong> <strong>Mirror Lowering With Reverse Rear </strong>” to activate mirror lowering when shifting into reverse gear:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/retrogolf63-d65eea5e.webp\"/></figure>\n<p><strong>6 </strong>– After this operation, click on the “Output” menu, then validate “OK”.  </p>\n<p>A message appears to inform you that the coding has been accepted.</p>\n<p><strong>Line 2:  </strong></p>\n<p><strong>3 –</strong> Click on<strong> “Select” </strong>, then click on<strong> “52 – Passenger door”.</strong></p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><em>Add <strong>256</strong> to the value</em></p>","caddy-2k-facelift-mute-push-to-talk-button":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose </strong>: Allows you to change the Push-To-Talk (PTT) button on the bottom left of your multifunction steering wheel, to act as a mute button for sound volume.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/></p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>16 – Multifunction Steering Wheel.”</strong><br/></p>\n<p><strong>4</strong> – Click on<strong>“Coding- 07</strong>”. then click on<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5 – </strong>Select <em>Byte<strong> 1</strong>: </em><br/><em>Bit <strong>3</strong>: Uncheck </em><em>“Multi-Function-Steering-Wheel (MFSW) with Push-To-Talk (PPT) Button installed</em>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/pttg6-da3300eb.webp\"/></figure>\n<p>The Push-to-Talk (PPT) button now acts as a mute button.</p>","caddy-2k-facelift-oil-temperature-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the Oil Temperature Display in your Grand ODB.  </p>\n<p>It sometimes happens that certain cars don’t have this value available in the ODB, including certain Sciroccos, TDIs and TSIs, and even R versions. Here’s a short tutorial to help you activate it and make it available in your ODB.  </p>\n<p><em>ATTENTION: Modification cannot be activated on all counters.</em><br/></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>10-Adaptation</strong>”, then in the window that appears, click on the drop-down menu and select this byte: <strong><em>(7) WIV : Service interval coding Oil level and temperature transmitter</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com_01_Sonde_Temperature-d-huile-Golf6R-TSI-TD-913f0cb0.webp\"/></figure>\n<p>English version: Coding For Service Interval Extension</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com_01_Sonde_Temperature-d-huile-Golf6R-TSI-TD-6650dcd4.webp\"/></figure>\n<p><strong>5 –</strong> <em>Select ”  <strong>Oil level/temp. transmitter connected to instrument holder   </strong>“in the second drop-down list</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/1Z0-920-843-G_Module17_Adaptation_7-WIV_v2-73e7e7f3.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_temp_huile_odb-b53aaa02.webp\"/></figure>","caddy-2k-facelift-programming-a-remote-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program remote controls with the vehicle’s immobilizer.<br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Ignition Authorization)</strong>, you cannot program a new remote control using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>“09 – Cent. Elect.”</strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the process.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>7 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 7 slots filled; delete the remote controls using the <strong>“Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/programmertelecommande-51bf4068.webp\"/></figure>","caddy-2k-facelift-remove-alarm-belt":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/></p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte “<strong>1</strong>” <br/>Then uncheck Bit “<strong>1</strong>”: “<strong>Seatbelt warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","caddy-2k-facelift-resetting-the-remote-controls":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle. </p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“Program a Remote Control”</strong> tutorial <strong>.</strong><br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Start Authorization)</strong>, you cannot delete the remote controls using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong><strong>“09 – Cent. Elect.”</strong></strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","caddy-2k-facelift-selective-door-unlocking":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose </strong>: Used to set up selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong><strong>Line 1:</strong></strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>09 – Power Plant.</strong>“</p>\n<p><strong>4 – </strong> Click “<strong>Encoding – 07</strong>,” then “<strong>Long Coding Helper”</strong></p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit<strong> 3: </strong> Check “Selective Central Locking active (Single Door Locking)” </em> </p>","caddy-2k-facelift-speed-limit-display-rns-510":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose </strong>: to display the speed limit on the RNS 510 navigation screen.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”. Then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong><br/>Activate Bit <strong>2</strong>: Speed Threshold for Destination Input active</p>\n<p>+ use voice command to activate Bit 3: Speed Threshold for Speech Destination Input active</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510speed-9dcbaa67.webp\"/></figure>","caddy-2k-facelift-start-stop-deactivation":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose:</strong> to disable Start and Stop completely.  <br/><br/><br/><strong><em>Only compatible with Gateway 7N0! Temperature deactivation method. </em></strong> <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Long Adaptation – 0A”</strong>.<br/><br/><strong>5</strong> – Select Channel<strong>“13</strong><br/><br/><strong>6</strong> – In new value, select<strong>“D02000</strong>” (default value = <strong>002000</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/gof6startstop-1024x528-699ec970.webp\"/></figure>","caddy-2k-facelift-activate-daytime-running-lights-with-fog-lamps-drl":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 3 facelift 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-3-2k-95c9f15d.webp\"/></figure>\n<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights.  </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1</strong><em> </em>:</p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte <strong>14: </strong> </em><br/>Set <em>Bit <strong>1</strong> </em> </p>","caddy-2k-activate-leaving-home-without-light-sensor":"<p><strong>Purpose</strong>: automatically switches on the headlights each time the vehicle is unlocked.  </p>\n<p>The headlights will come on whether it’s day or night. They stay on for about 30 sec.   </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>5</strong>: Check “Driving Light Assistance When Leaving Home active”</em></p>","caddy-2k-activate-turn-signals-in-us-mode":"<p><strong>Purpose:</strong> to activate US indicators. (Caddy phase 1 only)   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>Byte 7</strong>: Enter value<strong> 32</strong> in <strong>Dec</strong> box<br/>(value in % of intensity, origin: 0)</p>\n<p>Decimal examples shown in yellow in the image:<br/>14 (corresponds to a 20% variation in the indicator lights)<br/>1E (corresponds to a 30% variation in the indicator lights)<br/>28 (corresponds to a 40% variation in the indicator lights)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-937-049-Q_Module09_Byte7-16502f21.webp\"/></figure>","caddy-2k-adjust-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>2</strong>: </em><br/> Bits<em><strong> 0-7</strong></em> (187, 205 or 237 to increase sensitivity, or 45, 40 or 33 to decrease sensitivity)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightsensorg5-1e88d9a5.webp\"/></figure>","caddy-2k-ambient-lighting-intensity":"<p><strong>Purpose:</strong> Used to adjust ambient lighting intensity.  </p>\n<p><strong>Procedure</strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 05</strong> (Footwell Lightning Dimming)  </p>\n<p><strong>6 –</strong> Select intensity from 20 to 100% (in 1% increments)</p>","caddy-2k-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes the windows and sunroof when it rains. </p>\n<p>The vehicle must be locked using the remote control for this to work. </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf561-c90da3e5.webp\"/></figure>\n<p><strong>5</strong> – Select module “2” and click ” <strong>Long Coding Helper</strong> “:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitregolf56-9439cbb9.webp\"/></figure>\n<p><strong>6</strong> – In the window that appears, select byte 0 and check bit 2, <strong>“Rain Closing active</strong>,” to enable the windows and roof to close when it rains:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-5-d61c5dd9.webp\"/></figure>\n<p>7 – After completing this step, click on the “Exit” menu</p>\n<p> Then click “OK”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Vag-Com-Fermeture-Automatique-des-vitres-7-353fb01b.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click <strong>“46 – Central Conv”</strong> </p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5 –</strong> Then click <strong>” <strong>Long Coding Helper</strong> “</strong></p>\n<p><em>Byte 9: </em><br/><em>Bit 1: Check “Rain Closing (0 = nonrecurring / 1 = permanent)” </em><br/><em>Bit 2: Uncheck “Comfort Closing via Rain Light Sensor (Rain Closing) inactive” </em> </p>","caddy-2k-automatic-door-locking":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 04</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres_vw-auto-loc-ce03b1da.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4 : </strong> Check “Auto-Lock (automatic locking from 15 km/h)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","caddy-2k-automatic-door-unlocking":"<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Canal 05</strong></p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-door-unlock-798a1163.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (unlocking after removing key from ignition)”. </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","caddy-2k-automatic-headlamp-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","caddy-2k-automatic-headlight-activation-in-case-of-rain":"<p><strong>Purpose:</strong> to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte<strong> 0</strong> Bit <strong>1</strong>: Check “Rain Light Function Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","caddy-2k-comfort-blinker":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4 </strong>– Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 </strong>– Select Byte <strong>2</strong>,  </p>\n<p>Bit <strong>1</strong>: check<strong>“Comfort Turn Signal”.</strong> </p>","caddy-2k-coming-home-time-setting":"<p><strong>Purpose:</strong> Set the length of time the headlights remain on after the car is locked.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 01</strong> (Coming-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","caddy-2k-corner-lights-activation":"<p><strong>Purpose</strong>: to activate cornering lights with fog lamps.  </p>\n<p><strong>Modification only possible for vehicles with a 30 Byte power plant.</strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Internal Turn Light Control Algorithm active”.</em><br/><em>Bit <strong>3-4</strong>: Select “08 Turn Lights via fog lights” from the drop-down list</em></p>","caddy-2k-correction-of-odb-consumption-display":"<p><strong>Purpose</strong>: to correct the fuel consumption display on the on-board computer.  </p>\n<p><strong>Modification only possible on Mid/High range models</strong>. <br/><em>Note: modifications affect the display of instantaneous consumption, average consumption and fuel quantity.</em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on <strong>“17 – Instruments”</strong>. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation- 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> <em>“Consumption Correction”.</em></p>\n<p><em>Adjust consumption correction factor between 85% and 115%.</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g. l/100 km): DIS: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9,8 / 9,73 ? 105,38) Channel 3 will be changed from 100 to 105 <br/>Example 2: Calculation based on volume distance (e.g. MPG is: DIS: 23 MPG. Actual: 24 MPG. (100, 23/24 and 95.83) Channel 3 will be changed from 100 to 96</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/correction-consommation-odb-d51db18e.webp\"/></figure>","caddy-2k-cruise-control-activation-retrofit":"<p><strong>Purpose:</strong> to activate the speed governor after retrofitting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>01 – Motor</strong> “.</p>\n<p><strong>4</strong> – Click on ” <strong><strong>Access</strong></strong> – <strong> 11</strong> ” then enter the code ” <strong><em><strong>11463</strong></em></strong> ” </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/regulateur2-6871f13e.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>16 – Steering Wheel</strong>“.</p>\n<p><strong>4</strong> – Click on ” <strong>Coding – 07</strong> ” then </p>\n<p><em>The penultimate digit (0xxxx<strong>?</strong>x) is used to configure the cruise control.</em><br/><em>Enter <strong>2</strong> if you don’t have an on-board computer</em><br/><em>Set <strong>4</strong> if you have an on-board computer</em></p>\n<p>.</p>","caddy-2k-deactivate-brake-pad-warning-light":"<p><strong>Purpose: </strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>17 – Instruments</strong>.”<br/><br/><strong>4 – </strong>Click on <strong>“Coding –</strong> 07”  </p>\n<p><strong>5</strong> <em>–  <em>The third and fourth digits of the code (xx<strong>??</strong>x0x) are used to change the settings for the Instrument module. To turn off the brake pad warning light, subtract <strong>01</strong> from these digits. </em></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial code is: <strong>0027103</strong></p>\n<p>To turn off the brake pad warning light, simply recode it as follows: <strong>0026103 </strong><em>(27 – 01 = 26)</em></p>\n<p>To turn on the brake pad warning light: +01</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","caddy-2k-deactivate-burnt-out-bulb-display":"<p><strong>Purpose: </strong>To deactivate the burnt-out bulb indicator on the ODB (on-board computer). After adding LEDs, your on-board computer may indicate that the replaced bulb is out of order.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>18</strong> Bit<strong> 0</strong>: Uncheck “Cold Diagnosis License Plate Lights active” for plates</p>\n<p>the other bits for the other bulbs of your choice (see image)</p>\n<p>Byte 19 Bit 1: uncheck “Cold Diagnosis Front Parking Lights active” for night lights</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6231-0119a9fa.webp\"/></figure>\n<p>Or for all bulbs:</p>\n<p>Byte 2 Bit 2: Cold Lamp Diagnosis Active</p>\n<p><br/>Eliminate burnt-out bulb errors after coding.</p>","caddy-2k-deactivate-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate automatic activation of the rear windshield wiper during reversing when the front windshield wipers are operating.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 1 :</strong></em><br/><em><strong>Bit 7 </strong>: Uncheck “Rear Wiper with Front Wiper continiously active”.</em></p>\n<p><em><strong>Byte 2 : </strong></em><br/><em><strong>Bit 0</strong>: Uncheck “Rear Wiper with Front Wiper intermitent active”.</em></p>","caddy-2k-deactivate-windshield-washer-indicator":"<p><strong>Purpose </strong>: to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.<br/><br/><strong>4 </strong>– Click on “<strong>Coding – 07</strong>”.  </p>\n<p><strong>5</strong> <em>–  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To remove the ice-washer indicator, subtract <strong>04</strong> from these digits. </em></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding is: <strong>0027103</strong></p>\n<p>To remove the windscreen washer indicator, simply recode as follows: <strong>0023103 </strong><em>(27 – 04 = 23)</em></p>\n<p>To activate the ice washer indicator: +04</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","caddy-2k-defrost-time-setting":"<p><strong>Purpose:</strong> to set the operating time for mirror and rear window defrosting.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong> then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 03</strong> (Rear Window &amp; Outside Mirror Heater Activation Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>1 to 254 min</strong> (in 1 min increments).</p>","caddy-2k-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> –  <em>The third and fourth coding digits (xx<strong>??</strong>x0x) are used to modify Instrument module options. To suppress the belt alarm, subtract <strong>2</strong> from these digits. </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-Golf5-2c5d8d07.webp\"/></figure>\n<p>In the example above, the initial coding (with belt alarm) is: <strong>0023103</strong></p>\n<p>To delete the belt alarm, simply recode as follows: <strong>0021103 </strong><em>(23 – 02 = 21)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","caddy-2k-display-speed-on-rcd-300":"<p><strong>Purpose:</strong> To add a driving-school mode view to the RCD 300 that displays speed (also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“56 – Radio</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>” “Driving School Function”.<br/><br/><strong>7</strong> – Set value to <strong>1</strong>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RCD300_Module56_Channel02-3c0994f0.webp\"/></figure>\n<p>To activate the function:<br/>– Switch off the RCD-300<br/>– Press the MENU button<br/>– Keep the MENU button pressed and switch on the RCD-300.</p>\n<p><em>(To return to normal display, execute the same sequence)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_rcd300-efa2d2ba.webp\"/></figure>","caddy-2k-door-lock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.<br/><br/><strong>4 – </strong> Click “<strong>Adaptation – 10</strong>“</p>\n<p><strong>Channel 11</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2: </strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“46 – Module Confort</strong>”.<br/><br/> 4<strong>– </strong> Click on<strong>“Coding – 07</strong>” then “<strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>0: </strong> Check “Locking Confirmation (Blink) via Door Locks” (confirmation with flashing lights)</em><br/><em>Bit <strong>1: </strong> Tick “Locking Confirmation (Horn) via Door Locks” (confirmation with beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","caddy-2k-door-lock-confirmation-remote-control":"<p><strong>Purpose: </strong> Allows you to configure the door lock confirmation when using the remote control. </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 10</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vagcom-golf5-e5c80be6.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Locking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3: </strong> Tick “Locking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/locking_196-096e4b1a.webp\"/></figure>","caddy-2k-door-unlock-confirmation-key":"<p><strong>Purpose: </strong> Allows you to configure the door unlock confirmation when using the key.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 08</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Unlocking Confirmation (Blink) via Door Locks” (confirmation with blinking lights)</em><br/><em>Bit <strong>1</strong>: Check “Unlocking Confirmation (Horn) via Door Locks” (confirmation with a beep or horn)</em></p>","caddy-2k-door-unlock-confirmation-remote-control":"<p><strong>Purpose </strong>: to set the door unlock confirmation when using the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 07</strong></p>\n<p><em>Set the value to 0 (no confirmation)</em><br/><em>Set the value to 1 (confirmation with turn signals)</em><br/><em>Set the value to 2 (confirmation with beep/horn)</em><br/><em>Set the value to 3 (confirmation with turn signals and a beep/horn)</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte<strong> 10</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Unlocking Confirmation (Blink) via Remote Control” (confirmation with flashing lights)</em><br/><em>Bit <strong>3</strong>: Tick “Unlocking Confirmation (Horn) via Remote Control” (confirmation with Beep/Horn)</em></p>","caddy-2k-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates brake lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>","caddy-2k-fold-down-mirrors-with-ignition-off-and-door-open":"<p><strong>Purpose </strong>: Allows mirrors to be folded down even after the ignition has been switched off and a door opened.  </p>\n<p><em>(Also enables windows and sunroof to be closed)</em> </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>46 – Comfort Module</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><em>Byte<strong> 6</strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “Power Windows/Sunroof disabled after door Opening”.</em></p>","caddy-2k-headlamp-washer-duration-setting":"<p><strong>Purpose:</strong> Allows you to set how long the headlight washers remain activated.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 04</strong> (Headlight Washer Activation Time)  </p>\n<p><strong>6</strong> – Select a duration between <strong>50 and 10,000 ms</strong> (in 50-ms increments).</p>","caddy-2k-leaving-home-time-setting":"<p><strong>Purpose:</strong> to set the length of time the headlights remain on after the car is unlocked.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</strong> </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on <strong>“Adaptation – 10”</strong> </p>\n<p><strong>5</strong> – Select <strong>Channel 02</strong> (Leaving-Home Time)  </p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 sec</strong> (in 1sec increments).</p>","caddy-2k-modify-power-steering-hardness":"<p><strong>Purpose </strong>: to adjust the hardness of the power steering for a softer or harder steering wheel.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.</strong><br/><br/><strong>4 </strong>– Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5 – </strong>Select<strong> Channel 1 </strong>, <em>set a value between<strong> 1</strong> and <strong>15</strong> depending on your hardness preference</em>.</p>\n<p><strong>Or Line 2: (If channel 1 is unavailable)</strong>:<br/><br/> 3 – Click on<strong>“Select</strong>” then click on<strong>“44 – Direction assistée” / “44-steering assist.”</strong><br/><br/> 4<strong>– </strong> Click on<strong>“Coding – 07</strong>”.</p>\n<p><strong>5 – </strong>Select :</p>\n<ul>\n<li>xxx1x for smooth steering</li>\n<li>xxx2x for sports management</li>\n<li>xxx3x for hard steering</li>\n<li>xxx4x for harder steering</li>\n<li>xxx5x for very hard steering</li>\n</ul>","caddy-2k-one-touch-window-closure":"<p><strong>Purpose</strong>: to activate closing and opening of the windows and sunroof with the remote control <strong>WITHOUT </strong>remaining pressed until the windows are completely closed.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition turned off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Central Conv.”</strong></p>\n<p><strong>4</strong> – Click ” <strong>Encoding 07</strong>,” then “Long Coding Helper”</p>\n<p><strong>5 –</strong> <em>Byte 6: </em><br/><em>Bit 6: Check “Comfort Function Automatic Closing”</em></p>\n<ul>\n<li>Uncheck “Comfort function power windows/sunroof via remote control inactive”.</li>\n<li>Check “Comfort opening power windows via remote control active”.</li>\n<li>Check “Comfort closing power windows via remote control active”.</li>\n<li>Check “Closing sunroof via remote control active” (sunroof)</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ComfortConv-byte6-9f2c129f.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>46 – Comfort Module.”</strong><br/><br/><strong>4 – </strong>Click “ <strong>Adaptation – 10”</strong> </p>\n<p><strong>Channel 17</strong> (Comfort function)</p>\n<p><em>Set value to 1</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_0944-1024x741-ec4d5180.webp\"/></figure>\n<p><em>Pressing the remote control’s close button for 3 seconds will first lock the doors and then close the windows, without having to keep the button pressed until they are fully closed</em>.</p>","caddy-2k-permanent-headlamp-deactivation-scandinavian":"<p><strong>Purpose: Allows you </strong>to disable the low beams that are always on; they are activated only when set to “Auto,” and during the day, only the parking lights are on. (Disable Scandinavian Mode)   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Uncheck Bit <strong>3</strong></p>","caddy-2k-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program the remote controls with the vehicle’s immobilizer.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the procedure.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>4 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 4 slots filled; delete the remote controls using the <strong> “Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel01-10148edb.webp\"/></figure>","caddy-2k-reset-the-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle.</p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“How to Program a Remote Control”</strong> tutorial <strong>.</strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","caddy-2k-selective-door-unlocking":"<p><strong>Purpose </strong>: Used to set up selective door unlocking. </p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>46 – Comfort Module</strong>“.<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>Channel 03</strong></p>\n<p><em>Set value to 1</em></p>\n<p><strong>Line 2:</strong></p>\n<p>If the adaptation channel is not activated.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Opening)” </em> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Verrouillage-automatique-des-portieres-1K0_Module4-be0b33ff.webp\"/></figure>","caddy-2k-activate-daytime-running-lights-with-fog-lamps-drl":"<p><strong>Purpose</strong>: Allows fog lights to be used as daytime running lights.  </p>\n<p><strong>Procedure</strong>: <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><strong>6 –</strong> <em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Daytime Running Lights (North America)”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/scandinavie_194-c7df4fa8.webp\"/></figure>\n<p><strong>7 – </strong> <em>Byte<strong> 17</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Daytime Running Light with dimmed Low Beam” (or “Daytime Running Light via Fog Lights,” depending on your version of VCDS)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ab_975-e7b60077.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/veilleusejour3-c639151f.webp\"/></figure>\n<p><strong>8-</strong> Adjusting the fog light intensity (from 1% to 99%)</p>\n<p><em>Byte 20: </em><br/><em>Change the value in the Dec box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/VagComByte20-adce5646.webp\"/></figure>","caddy-4-2k-activate-off-road-mode-on-discover-pq":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> to add Offroad mode to Discover PQ with navigation.  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-compass_0x15</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass_over-threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<hr/>\n<p>Restart the Discover Media PQ (hold down the ON/OFF button for at least 5 seconds).</p>\n<p>Depending on your hardware and firmware, the off-road menu may appear directly in the Menu, or it may be hidden:<br/>Press the VOICE-MENU-NAV buttons to access the secret menu, where you’ll now find the OFFROAD screen:  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroadpq-1024x768-39023fd7.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroadmenupq-1024x619-dc3e8b4c.webp\"/></figure>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroad-1024x631-441bee99.webp\"/></figure>","caddy-4-2k-activate-rearview-camera-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the reversing camera after it has been retrofitted to the Discover PQ.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>6</strong> – Select byte <strong>19</strong><br/>. Then set bit <strong>4</strong> to “Rear View Camera (RVC) Low installed (PR-KA1).”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/C25A41FA-66F7-4FC9-B7F4-1761395A1D01-1024x483-11bbd3cf.webp\"/></figure>\n<p><strong><strong><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong></strong></strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>0</strong><br/>. Then set bit <strong>5</strong> to “Rear View Camera installed.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/CA86A611-2F74-4201-B791-7A74BC107A01-1024x482-c9f00e16.webp\"/></figure>\n<p><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The 2 pins of the reversing camera are used in the 12-pin quadlock (blue). Usable cable set: Part no. 000 979 009 E <br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","caddy-4-2k-activate-the-discover-hidden-menu":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) on Discover MIB2.  </p>\n<p>/!\\ Caution: Making certain changes in the hidden menu may cause MIB2 to freeze or no longer start /!\\</p>\n<p><em>For Caddy 4 (radio display like Golf 7).  </em><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Developer mode</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value<strong>“activated</strong>”.</p>\n<p><em>Restart MIB2, keep MENU button pressed until testmode menu appears</em><br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode-bfa51f40.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode2-1024x576-7a0c833c.webp\"/></figure>","caddy-4-2k-deactivate-mirrorlink":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to disable or remove MirrorLink from App-Connect on the MIB Discover PQ. The MirrorLink service has not been natively available on Android since June 1, 2020. For a direct connection to Android Auto.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicle configuration-Mirror_link</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Disabled</strong>” and confirm.</p>","caddy-4-2k-disable-am-frequency-on-discover":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the AM radio frequency on the Discover PQ (the AM radio frequency is rarely used, unlike the FM radio frequency). <br/><em><em>For Caddy 4 (Radio display like Golf 7). </em></em> </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable</strong></p>\n<figure>\n</figure>","caddy-4-2k-enable-usb-port-for-iphone-carplay-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the USB port for iPhone CarPlay accounting (after activating App Connect and changing the USB and/or USB cable) for Discover MIB2 PQ (after 2015). (Retrofit) </p>\n<p>For firmware references: <br/>MST2_EU_VW_PQ_P02XXT</p>\n<p>Modify the MIB2 coding and adaptation to recognize the new USB port (USB connector ref 5Q0 035 726 E) for both CarPlay and USB multimedia playback. A coding pin on the connector needs to be modified.  </p>\n<p><strong><a href=\"#/t/app-connect-carplay-activation\">–&gt; App Connect Activation for CarPlay and Android Auto</a><br/><a href=\"https://www.vag-custom.fr/produit/prise-usb-aux-vw-golf-7-carplay-media-mib2-5q0-035-726-e/\" rel=\"noopener\" target=\"_blank\">–&gt; USB/AUX Port for VW Golf 7 CarPlay Media MIB2 5Q0 035 726 E on VAG Custom</a></strong><br/><a href=\"#/vw/caddy-2k/caddy-4-2k-deactivate-mirrorlink\"><strong>–&gt; Disable MirrorLink</strong></a><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Codage- 07</strong>” then click on<strong>“Assistant Codage Long</strong>”.<br/><br/><strong>5 </strong>– Select byte<strong>“19</strong>“<br/>Then check Bit<strong>“6-7</strong>” (C0 USB Configuration: USB and iPhone Functionality)<br/><br/><strong>Ligne 2 <strong>(optional)</strong> :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Interface for external media activation – connection 1</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value “<strong><strong>activated</strong></strong>“<br/><br/><br/></p>\n<figure>\n<blockquote><a href=\"https://www.vag-custom.fr/produit/activation-app-connect-pour-volkswagen/\" rel=\"noopener\" target=\"_blank\">Activation APP CONNECT pour Volkswagen</a></blockquote>\n</figure>\n<figure>\n<blockquote><a href=\"https://www.vag-custom.fr/produit/prise-usb-aux-vw-golf-7-carplay-media-mib2-5q0-035-726-e/\" rel=\"noopener\" target=\"_blank\">Prise USB / AUX VW Golf 7 CarPlay Media MIB2 5Q0 035 726 E</a></blockquote>\n</figure>","caddy-4-2k-fan-speed-display-on-air-conditioning-in-auto-mode":"<figure><img alt=\"VAG Coding VCDS ODBeleven VW Caddy 4 2K\" decoding=\"async\" loading=\"lazy\" src=\"img/vw-caddy-4-2k-d457610c.webp\"/></figure>\n<p><strong>Purpose:</strong> to display fan speed when automatic air-conditioning mode is activated. (Climatronic fan speed display Auto mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>” /<strong>“08 – Auto HVAC</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Blower Status Display in Auto-Mode active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5G0-907-044-R_Module08_Byte11_v2-939963df.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/affichageclimautomqb-f32e9600.webp\"/></figure>"};
